custom_css:
/* Al Ihsan Hospital – v7 – Hide header (brute force) + Logo banner (resized) */

/* ── Hide the top navbar / native page header completely ── */
.navbar, header.navbar, .navbar-default,
nav.navbar, .top-bar, #navbar, .site-header,
.website-header, #header, .page-head, .navbar-brand,
.web-form-banner, .web-form-header img {
  display: none !important;
}



body {
  background: #eef2f7 !important;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif !important;
  padding-top: 0 !important;
  margin-top: 0 !important;
}

/* Remove body padding added for navbar */
body.sticky-top, body[style*="padding-top"] {
  padding-top: 0 !important;
}

/* ── Wrapper ── */
.web-form-wrapper {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  padding: 0 12px !important;
  margin-top: 0 !important;
}

/* Card */
.web-form-page {
  background: #fff !important;
  border-radius: 16px !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.09) !important;
  border: none !important;
  padding: 0 0 28px !important;
  margin: 12px 0 24px !important;
  overflow: hidden !important;
}

/* ── Banner at top of card (logo) ── */
.web-form-page::before {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 110px !important;
  background-color: #1a237e !important;
  background-image: url('data:image/png;base64,') !important;
  background-repeat: no-repeat !important;
  background-position: center center !important;
  background-size: auto 70px !important;
  margin-bottom: 20px !important;
}

/* Remove inner card box */
.web-form-page .section-body,
.web-form-page .form-section,
.web-form-page .card,
.web-form-page .frappe-card,
.web-form-page .web-form-body > div,
.web-form-page form > div {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* Add padding to form content below banner */
.web-form-page .web-form-body,
.web-form-page > div:not(:first-child) {
  padding: 0 20px !important;
}

/* Title */
.web-form-page h3,
.web-form-page h2,
.page-title {
  font-size: 17px !important;
  font-weight: 700 !important;
  color: #0f2942 !important;
  text-align: center !important;
  margin: 0 0 20px !important;
  padding: 0 20px !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
}

/* Divider */
.web-form-page hr { border-color: #f0f4f8 !important; margin: 0 20px 16px !important; }

/* Hide "Not Saved" */
.indicator-pill, .indicator,
.title-area .badge, .breadcrumb { display: none !important; }

/* Kill ALL Bootstrap columns */
[class*="col-xs-"], [class*="col-sm-"],
[class*="col-md-"], [class*="col-lg-"] {
  width: 100% !important;
  float: none !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  display: block !important;
}
.row { margin: 0 !important; }
.row::before, .row::after { display: none !important; }

/* Field blocks */
.frappe-control, .form-group {
  display: block !important;
  width: 100% !important;
  margin-bottom: 14px !important;
  float: none !important;
  clear: both !important;
  padding: 0 20px !important;
  box-sizing: border-box !important;
}

/* Labels above inputs */
.frappe-control .control-label,
.form-group label, .control-label {
  display: block !important;
  width: 100% !important;
  float: none !important;
  text-align: left !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  color: #334155 !important;
  margin-bottom: 5px !important;
  padding: 0 !important;
}

.frappe-control .control-input-wrapper,
.frappe-control .input-max-width,
.form-group .controls {
  width: 100% !important;
  max-width: 100% !important;
  float: none !important;
  padding: 0 !important;
}

/* Inputs */
input[type="text"], input[type="email"],
input[type="number"], input[type="date"],
input[type="tel"], select, textarea, .form-control {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  display: block !important;
  border: 1.5px solid #dde3ea !important;
  border-radius: 10px !important;
  padding: 11px 13px !important;
  font-size: 15px !important;
  color: #0f2942 !important;
  background: #f8fafc !important;
  box-shadow: none !important;
  outline: none !important;
  min-height: 44px !important;
  height: auto !important;
  -webkit-appearance: none !important;
  appearance: none !important;
  font-family: inherit !important;
  transition: border-color 0.2s, box-shadow 0.2s !important;
}

input:focus, select:focus, textarea:focus, .form-control:focus {
  border-color: #1a6fa8 !important;
  box-shadow: 0 0 0 3px rgba(26,111,168,0.13) !important;
  background: #fff !important;
  outline: none !important;
}

textarea, textarea.form-control {
  min-height: 100px !important;
  resize: vertical !important;
  line-height: 1.6 !important;
}

/* Stars */
.rating svg, .rating .icon,
[data-fieldtype="Rating"] svg {
  width: 30px !important; height: 30px !important;
  min-width: 30px !important;
  color: #cbd5e1 !important; fill: #cbd5e1 !important;
  cursor: pointer !important;
}
.rating .active svg, .rating svg.active {
  color: #f59e0b !important; fill: #f59e0b !important;
}

/* Buttons */
.web-form-footer, .form-footer, [class*="web-form"] .btn-toolbar {
  display: flex !important;
  flex-direction: row !important;
  gap: 10px !important;
  margin-top: 20px !important;
  padding: 0 20px !important;
}

.btn-primary, button[type="submit"], .btn-form-submit {
  flex: 1 !important;
  background: #1a6fa8 !important;
  background-image: none !important;
  color: #fff !important;
  border: none !important;
  border-radius: 10px !important;
  padding: 13px !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  box-shadow: 0 4px 12px rgba(26,111,168,0.25) !important;
  text-shadow: none !important;
}
.btn-primary:hover { background: #155d8f !important; }

.btn-default, .btn-secondary {
  flex: 1 !important;
  background: transparent !important;
  border: 1.5px solid #dde3ea !important;
  border-radius: 10px !important;
  color: #607080 !important;
  padding: 12px !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  cursor: pointer !important;
}

.help-block, .invalid-feedback {
  color: #e74c3c !important;
  font-size: 12px !important;
  margin-top: 4px !important;
}
